import "server-only";

import { syncStatusSchema } from "@/features/sync/schemas/sync-status-schema";
import db from "@/lib/db";

// Classify only diagnostics generated by the existing ingestion pipeline. Never
// return an internal diagnostic or infer an official-session/token failure.
export function classifySyncAttempt(
    sync: { status: string; errorMessage: string | null; startedAt: Date },
    now: Date
) {
    if (sync.status === "processing") {
        const age = now.getTime() - sync.startedAt.getTime();
        return age >= 900000
            ? "timedOut"
            : age >= 600000
              ? "delayed"
              : "processing";
    }
    if (sync.status === "completed")
        return sync.errorMessage ? "partial" : "completed";
    return sync.errorMessage === "동기화 처리 시간이 초과되었습니다."
        ? "timedOut"
        : "failed";
}

export async function getSyncStatus(userId: number, now = new Date()) {
    const [attempts, played, judgement, timing] = await Promise.all([
        db.dataSync.findMany({
            where: { userId: userId },
            orderBy: [{ startedAt: "desc" }, { id: "desc" }],
            take: 5,
            select: {
                id: true,
                status: true,
                syncScope: true,
                receivedPlays: true,
                insertedPlays: true,
                changedRecords: true,
                errorMessage: true,
                startedAt: true,
                completedAt: true,
            },
        }),
        db.musicChart.count({
            where: {
                OR: [
                    {
                        playData: {
                            some: { userId: userId, playCount: { gt: 0 } },
                        },
                    },
                    { playHistory: { some: { userId: userId } } },
                ],
            },
        }),
        db.musicChart.count({
            where: {
                OR: [
                    {
                        playData: {
                            some: {
                                userId: userId,
                                playCount: { gt: 0 },
                                judgeSjust: { not: null },
                                judgeJust: { not: null },
                                judgeGood: { not: null },
                                judgeMiss: { not: null },
                                judgeNear: { not: null },
                            },
                        },
                    },
                    {
                        playHistory: {
                            some: {
                                userId: userId,
                                judgeSjust: { not: null },
                                judgeJust: { not: null },
                                judgeGood: { not: null },
                                judgeMiss: { not: null },
                                judgeNear: { not: null },
                            },
                        },
                    },
                ],
            },
        }),
        db.chartPlayHistory.groupBy({
            by: ["chartId"],
            where: {
                userId: userId,
                fastCount: { not: null },
                slowCount: { not: null },
            },
        }),
    ]);
    const recordCounts = await db.chartRecordSnapshot.groupBy({
        by: ["syncId"],
        where: {
            userId: userId,
            syncId: {
                in: attempts
                    .filter(
                        (attempt) =>
                            attempt.syncScope === "full" &&
                            attempt.status === "completed"
                    )
                    .map((attempt) => attempt.id),
            },
            playCount: { gt: 0 },
        },
        _count: { _all: true },
    });
    const playedChanges = new Map(
        recordCounts.map((row) => [row.syncId, row._count._all])
    );
    const latest = attempts[0];
    const full = latest?.syncScope === "full";
    const firstFullImport = Boolean(
        latest?.status === "completed" &&
        full &&
        (playedChanges.get(latest.id) ?? 0) > 3 &&
        !(await db.dataSync.findFirst({
            where: {
                userId: userId,
                status: "completed",
                syncScope: "full",
                id: { not: latest.id },
                startedAt: { lte: latest.startedAt },
            },
            select: { id: true },
        }))
    );
    const chart = {
        select: {
            musicIdx: true,
            difficulty: true,
            level: true,
            music: { select: { title: true } },
        },
    } as const;
    const changes =
        latest?.status !== "completed" || firstFullImport
            ? []
            : full
              ? await db.chartRecordSnapshot.findMany({
                    where: {
                        userId: userId,
                        syncId: latest.id,
                        playCount: { gt: 0 },
                    },
                    orderBy: { id: "desc" },
                    take: 3,
                    select: { score: true, chart },
                })
              : await db.chartPlayHistory.findMany({
                    where: { userId: userId, firstSyncId: latest.id },
                    orderBy: { id: "desc" },
                    take: 3,
                    select: { score: true, chart },
                });
    // 새 업적(2026-09-24 E1) — 판정은 동기화 끝에서 하므로 그 시도의 시작 ~ 완료 사이에 얻은 단계
    const newAchievements =
        latest?.status === "completed" && latest.completedAt
            ? await db.userAchievement.findMany({
                  where: {
                      userId: userId,
                      achievedAt: {
                          gte: latest.startedAt,
                          lte: latest.completedAt,
                      },
                  },
                  orderBy: [{ tier: "desc" }, { id: "asc" }],
                  take: 100,
                  select: { key: true, tier: true },
              })
            : [];
    return syncStatusSchema.parse({
        observedAt: now.toISOString(),
        attempts: attempts.map((sync) => {
            const excluded =
                /^DB에 등록되지 않은 채보 (\d+)개를 건너뛰었습니다:/.exec(
                    sync.errorMessage ?? ""
                );
            return {
                id: sync.id,
                status: classifySyncAttempt(sync, now),
                scope: sync.syncScope === "full" ? "full" : "recent",
                startedAt: sync.startedAt.toISOString(),
                completedAt: sync.completedAt?.toISOString() ?? null,
                receivedPlays: sync.receivedPlays,
                insertedPlays: sync.insertedPlays,
                changedRecords:
                    sync.syncScope === "full"
                        ? (playedChanges.get(sync.id) ?? 0)
                        : 0,
                excludedCount: excluded ? Number(excluded[1]) : null,
                newAchievements: sync.id === latest?.id ? newAchievements : [],
            };
        }),
        coverage: { played, judgement, timing: timing.length },
        firstFullImport,
        previews: changes.map(({ score, chart }) => ({
            score,
            musicId: chart.musicIdx,
            title: chart.music.title,
            difficulty: chart.difficulty,
            level: chart.level,
        })),
        retryAfter: latest
            ? Math.max(
                  0,
                  Math.min(
                      30,
                      Math.ceil(
                          (30000 -
                              (now.getTime() - latest.startedAt.getTime())) /
                              1000
                      )
                  )
              )
            : 0,
    });
}
